/*
 * A042706  Numerators of continued fraction convergents to sqrt(883).
 * https://oeis.org/A042706
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the n‑th convergent of sqrt(883). Let a_0 =
 *            ⌊√883⌋ = 29. Subsequent partial quotients a_i are generated by
 *            the classical continued‑fraction algorithm for √883: m₀=0, d₀=1,
 *            mᵢ₊₁ = dᵢ·aᵢ – mᵢ, dᵢ₊₁ = (883 – mᵢ₊₁²) / dᵢ, aᵢ₊₁ = ⌊(a₀ +
 *            mᵢ₊₁) / dᵢ₊₁⌋. The convergents' numerators sa...
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 17, u64 n <= 38, u128 n <= 74,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

/* Computes the nth term of OEIS sequence A042706. */
seq_t a(idx_t n)
{
    /* Parameters for sqrt(883) */
    const unsigned long long D   = 883ULL;
    const unsigned long long a0  = 29ULL;          /* floor(sqrt(883)) */
    unsigned long long m   = 0ULL;                /* m₀ */
    unsigned long long d   = 1ULL;                /* d₀ */
    unsigned long long a_i = a0;                  /* a₀ */

    /* Convergent numerators */
    seq_t p_prevprev = 0;      /* p₋₂ */
    seq_t p_prev     = 1;      /* p₋₁ */
    seq_t p_curr;

    for (idx_t i = 0; i <= n; ++i) {
        /* Compute pᵢ */
        p_curr = (seq_t)a_i * p_prev + p_prevprev;
        if (i == n)
            return p_curr;

        /* Prepare next partial quotient aᵢ₊₁ */
        unsigned long long m_next = d * a_i - m;
        unsigned long long d_next = (D - m_next * m_next) / d;
        unsigned long long a_next = (a0 + m_next) / d_next;

        m   = m_next;
        d   = d_next;
        a_i = a_next;

        /* Shift for next iteration */
        p_prevprev = p_prev;
        p_prev     = p_curr;
    }

    /* Code never reaches here, but return 0 to silence compiler warnings. */
    return 0;
}
